// NLCL game runtime for Unity: keyboard/mouse input that works with both the
// legacy Input Manager and the new Input System package.  Generated by NLCL.
using UnityEngine;
#if ENABLE_INPUT_SYSTEM && !ENABLE_LEGACY_INPUT_MANAGER
using UnityEngine.InputSystem;
#endif

public static class NlclInput
{
    static int _clickFrame = -1;
    static string _clicked;

    /// <summary>True during the frame the key/button was pressed.</summary>
    public static bool Down(KeyCode k)
    {
#if ENABLE_INPUT_SYSTEM && !ENABLE_LEGACY_INPUT_MANAGER
        if (k == KeyCode.Mouse0) return Mouse.current != null && Mouse.current.leftButton.wasPressedThisFrame;
        if (k == KeyCode.Mouse1) return Mouse.current != null && Mouse.current.rightButton.wasPressedThisFrame;
        Key key = ToKey(k);
        return key != Key.None && Keyboard.current != null && Keyboard.current[key].wasPressedThisFrame;
#else
        return Input.GetKeyDown(k);
#endif
    }

    /// <summary>True while the key/button is held.</summary>
    public static bool Held(KeyCode k)
    {
#if ENABLE_INPUT_SYSTEM && !ENABLE_LEGACY_INPUT_MANAGER
        if (k == KeyCode.Mouse0) return Mouse.current != null && Mouse.current.leftButton.isPressed;
        if (k == KeyCode.Mouse1) return Mouse.current != null && Mouse.current.rightButton.isPressed;
        Key key = ToKey(k);
        return key != Key.None && Keyboard.current != null && Keyboard.current[key].isPressed;
#else
        return Input.GetKey(k);
#endif
    }

    public static bool AnyDown()
    {
#if ENABLE_INPUT_SYSTEM && !ENABLE_LEGACY_INPUT_MANAGER
        return Keyboard.current != null && Keyboard.current.anyKey.wasPressedThisFrame;
#else
        return Input.anyKeyDown;
#endif
    }

    /// <summary>Key given by name ("space", "a", "f1" ...); false if unknown.</summary>
    public static bool DownNamed(string name)
    {
        KeyCode k;
        if (System.Enum.TryParse(name, true, out k)) return Down(k);
        return false;
    }

    public static Vector2 MousePosition()
    {
#if ENABLE_INPUT_SYSTEM && !ENABLE_LEGACY_INPUT_MANAGER
        return Mouse.current != null ? Mouse.current.position.ReadValue() : Vector2.zero;
#else
        return Input.mousePosition;
#endif
    }

    /// <summary>Identifier of the entity clicked this frame (or null).</summary>
    public static string Clicked()
    {
        if (_clickFrame == Time.frameCount) return _clicked;
        _clickFrame = Time.frameCount;
        _clicked = null;
        if (!Down(KeyCode.Mouse0) || Camera.main == null) return null;
        Ray ray = Camera.main.ScreenPointToRay(MousePosition());
        RaycastHit hit;
        if (Physics.Raycast(ray, out hit, 1000f, ~0, QueryTriggerInteraction.Collide))
        {
            NlclEntity e = hit.collider.GetComponentInParent<NlclEntity>();
            if (e != null) _clicked = e.nlclId;
        }
        return _clicked;
    }

#if ENABLE_INPUT_SYSTEM && !ENABLE_LEGACY_INPUT_MANAGER
    static Key ToKey(KeyCode k)
    {
        switch (k)
        {
            case KeyCode.Return: case KeyCode.KeypadEnter: return Key.Enter;
            case KeyCode.LeftControl: return Key.LeftCtrl;
            case KeyCode.RightControl: return Key.RightCtrl;
        }
        if (k >= KeyCode.Alpha0 && k <= KeyCode.Alpha9) return Key.Digit0 + (k - KeyCode.Alpha0);
        Key r;
        return System.Enum.TryParse(k.ToString(), out r) ? r : Key.None;
    }
#endif
}
